def combinationSum3(k: int, n: int) -> list[list[int]]:
    res = []
    def backtrack(start, rem, curr):
        if len(curr) == k:
            if rem == 0: res.append(list(curr))
            return
        for d in range(start, 10):
            if d > rem: break
            curr.append(d)
            backtrack(d + 1, rem - d, curr)
            curr.pop()
    backtrack(1, n, [])
    return res

